        "Ar cilvēkiem un iestādēm zu bieži nozīmē pie vai uz.",
        "Ar īpašības vārdiem zu var nozīmēt pārāk.",
        "Konstrukcijā zu + nenoteiksme tas palīdz veidot nenoteiksmi: zu lernen, zu gehen."
